window.AUTH=window.AUTH||{};window.AUTH["17-1184"]={"d":"17-1184","id":"2018/17-1184","n":"Biestek v. Berryhill","briefs":[{"k":"petitioner","label":"Brief of petitioner Michael J. Biestek","date":"2018-08-27","url":"https://www.supremecourt.gov/DocketPDF/17/17-1184/60838/20180827164224077_17-1184%20ts.pdf","side":"pet","n":93},{"k":"respondent","label":"Brief of respondent Nancy A. Berryhill, Deputy Commissioner for Operations, Social Security Administration","date":"2018-10-15","url":"https://www.supremecourt.gov/DocketPDF/17/17-1184/67043/20181016145537448_17-1184bsUnitedStates%20-%20REVISED.pdf","side":"res","n":75},{"k":"reply","label":"Reply of petitioner Michael J. Biestek","date":"2018-11-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-1184/72019/20181114143756083_Biestek%20Reply%20Brief%20Updated%20A.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1184_1b82.pdf","tr":true,"items":[{"t":"case","label":"Adkins v. Astrue","cite":"226 F. App’x 600","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/226/600/","sum":"Rejecting claimant’s argument that ALJ violated Federal Rules of Evidence when considering medical reference text outside of the record.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"Alaura v. Colvin","cite":"797 F.3d 503","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/503/","by":{"0":"11","2":"9"}},{"t":"case","label":"Andreu ex rel. Andreu v. Secretary of Department of Health & Human Services","cite":"569 F.3d 1367","y":2009,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/569/1367/","by":{"0":"51"}},{"t":"case","label":"Baltimore & Ohio Railroad Co. v. Aberdeen & Rockfish Railroad Co.","cite":"393 U.S. 87","y":1968,"id":"1968/13","sc":1,"sum":"The Court held that the district court properly set aside the Commission’s ruling due to a lack of substantial evidence.","sumSrc":"Oyez","by":{"0":"31, 32","1":"37","2":"21"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"3","1":"5","2":"11"}},{"t":"case","label":"Barrett v. Barnhart","cite":"355 F.3d 1065","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/1065/","by":{"0":"26, 29","2":"15, 17"}},{"t":"case","label":"Binion ex rel. Binion v. Chater","cite":"108 F.3d 780","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/108/780/","by":{"0":"39"}},{"t":"case","label":"Bowen v. Yuckert","cite":"482 U.S. 137","y":1987,"id":"1986/85-1409","sc":1,"sum":"The Social Security Act (Act) defines \"disability\" as the \"inability to engage in any substantial gainful activity by reason of any medically determinable physical or mental impairment....\" 42 U. S. C. § 423(d)(1)(A). The Act also provides that an individual \"shall be determined to be under a disability only if his... impairment [is] of such severity that he is not only unable to do his previous work but cannot, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Brault v. Social Security Administration","cite":"683 F.3d 443","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/683/443/","by":{"0":"13, 35, 37","1":"8"}},{"t":"case","label":"Britton v. Astrue","cite":"521 F.3d 799","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/521/799/","by":{"0":"50","1":"54","2":"24"}},{"t":"case","label":"Califano v. Goldfarb","cite":"430 U.S. 199","y":1977,"id":"1976/75-699","sc":1,"sum":"The Court affirmed the District Court in holding the statute unconstitutional. Writing for a four-justice plurality, Justice William J. Brennan, Jr. described this situation as \"indistinguishable\" from the one in Weinberger v. Wiesenfeld , where a similar statute was invalidated. In this case, a female worker's family was less protected than the family of a male worker.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Chavez v. Berryhill","cite":"895 F.3d 962","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/962/","op":1,"by":{"0":"26, 50","1":"49"}},{"t":"case","label":"Consolidated Edison Co. of New York v. NLRB","cite":"305 U.S. 197","y":1938,"id":"scdb/1938-001","sc":1,"op":4,"sum":"1. The power of the Federal Government, and the provisions of the National Labor Relations Act, extend to the labor relations of public utilities engaged in supplying electrical energy, gas and steam, where the business and activities of the utilities are wholly within a State, and where the quantum of service rendered to customers for strictly intrastate uses is vast and greatly preponderant, but where, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"passim","2":"5, 6, 17"}},{"t":"case","label":"Daubert v. Merrell Dow Pharmaceuticals, Inc.","cite":"509 U.S. 579","y":1993,"id":"1992/92-102","sc":1,"sum":"Petitioners, two minor children and their parents, alleged in their suit against respondent that the children's serious birth defects had been caused by the mothers' prenatal ingestion of Bendectin, a prescription drug marketed by respondent. The District Court granted respondent summary judgment based on a well-credentialed expert's affidavit concluding, upon reviewing the extensive published scientific literature …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 44, 45","1":"25"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"op":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"0":"32","1":"24"}},{"t":"case","label":"Donahue v. Barnhart","cite":"279 F.3d 441","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/279/441/","op":2,"ar":2,"by":{"0":"28, 29, 39","1":"30, 54","2":"5"}},{"t":"case","label":"Elm Grove Coal Co. v. Director, Office of Workers’ Compensation Programs","cite":"480 F.3d 279","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/480/279/","by":{"0":"46"}},{"t":"case","label":"Federal Power Commission v. Florida Power & Light Co.","cite":"404 U.S. 453","y":1972,"id":"1971/70-38","sc":1,"sum":"The Federal Power Commission (FPC) properly deter/iined that the transfer of power from Florida Power & Light Co. (FP&L) to another Florida utility's \"bus\" (a transmission line into which subsidiary lines connect) and the simultaneous transfer of power from that utility's \"bus\" to a Georgia company gave the FPC jurisdiction over FP&L under § 201 (b) of the Federal Power Act, which grants jurisdiction to the FPC over …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34","1":"39, 40","2":"6"}},{"t":"case","label":"General Electric, Co. v. Joiner","cite":"522 U.S. 136","y":1997,"id":"1997/96-188","sc":1,"sum":"The Court held that abuse of discretion, the standard ordinarily applicable to review of evidentiary rulings, is the proper standard by which to review a district court's decision to admit or exclude expert scientific evidence.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"Gisbrecht v. Barnhart","cite":"535 U.S. 789","y":2002,"id":"2001/01-131","sc":1,"sum":"The Court held that section 406(b) does not displace contingent-fee agreements within the statutory ceiling; instead, section 406(b) instructs courts to review for reasonableness fees yielded by those agreements.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Heckler v. Campbell","cite":"461 U.S. 458","y":1983,"id":"1982/81-1983","sc":1,"sum":"The Secretary's use of the medical-vocational guidelines to determine a claimant's right to disability benefits does not conflict with the Social Security Act, nor are the guidelines arbitrary or capricious.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55, 56","1":"3, 5, 6, 28, 36","2":"14"}},{"t":"case","label":"Heckler v. Day","cite":"467 U.S. 104","y":1984,"id":"1983/82-1371","sc":1,"sum":"In a 5-to-4 opinion, the Court held that Congress already considered and expressly rejected the imposition of mandatory disability dispute-resolution deadlines. Such deadlines, according to congressional reports, would subordinate quality of service to timeliness.","sumSrc":"Oyez","by":{"0":"6","1":"53"}},{"t":"case","label":"Hendrix ex rel. G.P. v. Evenflo Co.","cite":"609 F.3d 1183","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/609/1183/","by":{"0":"51"}},{"t":"case","label":"Holtz v. Astrue","cite":"2007 WL 5323758","y":2007,"court":"W.D. Wis. Nov. 8","by":{"0":"51"}},{"t":"case","label":"Khuzaie v. Commissioner of Social Security","cite":"2016 WL 1253537","y":2016,"court":"N.D. Ind. Mar. 30","sum":"Rejecting argument that expert was required to provide data where applicant failed to request it.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Kumho Tire Co., Ltd. v. Carmichael","cite":"526 U.S. 137","y":1999,"id":"1998/97-1709","sc":1,"sum":"The Court held that a federal trial judge's \"gatekeeping\" obligation applies not only to \"scientific\" testimony, but to all expert testimony. Justice Breyer wrote for the Court that Federal Rule of Evidence 702 \"makes no relevant distinction between 'scientific' knowledge and 'technical' or 'other specialized knowledge.","sumSrc":"Oyez","by":{"0":"38","1":"46"}},{"t":"case","label":"Marsh v. Oregon Natural Resources Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"sum":"The Elk Creek Dam is part of a three-dam project designed to control the water supply in Oregon's Rogue River Basin. The Army Corps of Engineers (Corps) completed an Environmental Impact Statement (EIS) for the Elk Creek project in 1971, and, in 1980, released its final Environmental Impact Statement, Supplement No. 1 (FEISS). Since the Rogue River is a premier fishing ground, the FEISS paid special heed to water …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43"}},{"t":"case","label":"Maslenjak v. United States","cite":"137 S. Ct. 1918","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"McKinnie v. Barnhart","cite":"368 F.3d 907","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/907/","op":3,"ar":1,"by":{"0":"28, 29","1":"54","2":"5"}},{"t":"case","label":"Melendez-Diaz v. Massachusetts","cite":"557 U.S. 305","y":2009,"id":"2008/07-591","sc":1,"sum":"The Court found that a state forensic analyst's lab report prepared for use in a criminal prosecution is subject to the demands of the Sixth Amendment Confrontation Clause.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"NLRB v. Columbian Enameling & Stamping Co.","cite":"306 U.S. 292","y":1939,"id":"scdb/1938-055","sc":1,"op":1,"sum":"1. An order of the National Labor Relations Board requiring reinstatement' of employees based on a finding that the employer, on a date specified, had refused to bargain with their Union, held invalid, the finding not being sustained by evidence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 32, 33","1":"24, 26, 38, 42","2":"22"}},{"t":"case","label":"Perry v. Leeke","cite":"488 U.S. 272","y":1989,"id":"1988/87-6325","sc":1,"sum":"At the conclusion of petitioner's direct testimony in his state-court trial for murder and related offenses, the trial judge declared a 15-minute recess and ordered that petitioner not be allowed to talk to anyone, including his lawyer, during the break. In affirming petitioner's conviction, the South Carolina Supreme Court ruled that Geders v. United States, 425 U. S. 80-in which it was held that a trial court's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Powell v. Colvin","cite":"2014 WL 1643313","y":2014,"court":"N.D. Ind. Apr. 22","ar":1,"by":{"0":"40"}},{"t":"case","label":"Purdy v. Berryhill","cite":"887 F.3d 7","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/887/7/","by":{"0":"35"}},{"t":"case","label":"Ramzan v. Colvin","cite":"2015 WL 5921811","y":2015,"court":"N.D. Ill. Oct. 9","by":{"0":"53"}},{"t":"case","label":"Reynolds v. Astrue","cite":"2010 WL 2900356","y":2010,"court":"E.D. Wis. July 21","ar":1,"by":{"0":"40"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"op":6,"ar":2,"sum":"Rejecting a categorical rule pertaining to the substantiality of medical reports in a disability hearing.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"13, 19"}},{"t":"case","label":"Ronning v. Colvin","cite":"2015 WL 1912157","y":2015,"court":"N.D. Ill. Apr. 27","sum":"Rejecting argument that expert failed to support her testimony where she identified specific sources of data, explained her methodology, and was able on cross-examination to reconcile and explain differences between figures.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Shaibi v. Berryhill","cite":"883 F.3d 1102","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/1102/","by":{"0":"29","2":"8, 17"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"op":2,"sum":"Noting “the adjudicator’s duty to fully develop the record”.","sumSrc":"opinion","by":{"0":"48","2":"18"}},{"t":"case","label":"Sullivan v. Zebley","cite":"493 U.S. 521","y":1990,"id":"1989/88-1377","sc":1,"sum":"The child-disability regulations are inconsistent with the statutory standard of \"comparable severity.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"T-Mobile South, L.L.C. v. City of Roswell","cite":"135 S. Ct. 808","y":2015,"id":"2014/13-975","sc":1,"op":1,"sum":"The Court held that the Telecommunications Act of 1996 does not require localities to provide reasons for their denial of construction applications in the written denial notification as long as the reasons appear in some other sufficiently clear written record.","sumSrc":"Oyez","by":{"0":"30","1":"18, 24"}},{"t":"case","label":"ix United States Steel Mining Co. v. Director, Office of Workers’ Compensation Programs","cite":"187 F.3d 384","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/187/384/","by":{"0":"43"}},{"t":"case","label":"United States v. Downing","cite":"753 F.2d 1224","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/753/1224/","sum":"Recognizing that “[t]he danger that scientific evidence will mislead the [factfinder] might be greater, for example, where the [factfinder] is not presented with the data on which the expert relies, but must instead accept the expert’s assertions as to the accuracy of his conclusions”.","sumSrc":"brief:0","by":{"0":"47"}},{"t":"case","label":"United States v. Fosher","cite":"590 F.2d 381","y":1979,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/590/381/","sum":"Describing a common concern among courts that technical expert testimony poses “substantial danger of undue prejudice and confusion because of its aura of special reliability and trustworthiness”.","sumSrc":"brief:0","by":{"0":"47"}},{"t":"case","label":"Welsh v. Commissioner of Social Security","cite":"662 F. App’x 105","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/662/105/","op":1,"by":{"0":"35"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(b)","(b)(1)","(g)","(a)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"7, 1, 8, 35, 37, 1, 3, 7, 9, 18, 21","1":"2, 2, 2, 2"}},{"t":"usc","label":"42 U.S.C. § 414","url":"https://www.law.cornell.edu/uscode/text/42/414","by":{"0":"6"}},{"t":"usc","label":"42 U.S.C. § 423","url":"https://www.law.cornell.edu/uscode/text/42/423","subs":["(d)(2)(A)","(a)(1)(E)","(d)(1)(A)"],"stext":{"head":"§423. Disability insurance benefit payments","paras":[[0,"(a) Disability insurance benefits"],[0,"(1) Every individual who—"],[1,"(A) is insured for disability insurance benefits (as determined under subsection (c)(1)),"],[1,"(B) has not attained retirement age (as defined in section 416(l) of this title),"],[1,"(C) if not a United States citizen or national—"],[2,"(i) has been assigned a social security account number that was, at the time of assignment, or at any later time, consistent with the requirements of subclause (I) or (III) of section 405(c)(2)(B)(i) of this title; or"],[2,"(ii) at the time any quarters of coverage are earned—"],[3,"(I) is described in subparagraph (B) or (D) of section 1101(a)(15) of title 8,"],[3,"(II) is lawfully admitted temporarily to the United States for business (in the case of an individual described in such subparagraph (B)) or the performance as a crewman (in the case of an individual described in such subparagraph (D)), and"],[3,"(III) the business engaged in or service as a crewman performed is within the scope of the terms of such individual's admission to the United States.1"],[1,"(D) has filed application for disability insurance benefits, and"],[1,"(E) is under a disability (as defined in subsection (d))"],[0,"shall be entitled to a disability insurance benefit (i) for each month beginning with the first month after his waiting period (as defined in subsection (c)(2)) in which he becomes so entitled to such insurance benefits, (ii) in the case of an individual who has been medically determined to have amyotrophic lateral sclerosis, for each month beginning with the first month during all of which the individual is under a disability and in which the individual becomes entitled to such insurance benefits, or (iii) for each month beginning with the first month during all of which he is under a disability and in which he becomes so entitled to such insurance benefits, but only if he was entitled to disability insurance benefits which terminated, or had a period of disability (as defined in section 416(i) of this title) which ceased, within the 60-month period preceding the first month in which he is under such disability, and ending with the month preceding whichever of the following months is the earliest: the month in which he dies, the month in which he attains retirement age (as defined in section 416(l) of this title), or, subject to subsection (e), the termination month. For purposes of the preceding sentence, the termination month for any individual shall be the third month following the month in which his disability ceases; except that, in the case of an individual who has a period of trial work which ends as determined by application of section 422(c)(4)(A) of this title, the termination month shall be the earlier of (I) the third month following the earliest month after the end of such period of trial work with respect to which such individual is determined to no longer be suffering from a disabling physical or mental impairment, or (II) the third month following the earliest month in which such individual engages or is determined able to engage in substantial gainful activity, but in no event earlier than the first month occurring after the 36 months following such period of trial work in which he engages or is determined able to engage in substantial gainful activity. No payment under this paragraph may be made to an individual who would not meet the definition of disability in subsection (d) except for paragraph (1)(B) thereof for any month in which he engages in substantial gainful activity, and no payment may be made for such month under subsection (b), (c), or (d) of section 402 of this title to any person on the basis of the wages and self-employment income of such individual. In the case of a deceased individual, the requirement of subparagraph (C) may be satisfied by an application for benefits filed with respect to such individual within 3 months after the month in which he died."],[0,"(2) Except as provided in section 402(q) of this title and section 415(b)(2)(A)(ii) of this title, such individual's disability insurance benefit for any month shall be equal to his primary insurance amount for such month determined under section 415 of this title as though he had attained age 62 in—"],[1,"(A) the first month of his waiting period, or"],[1,"(B) in any case in which clause (ii) of paragraph (1) of this subsection is applicable, the first month for which he becomes entitled to such disability insurance benefits,"],[0,"and as though he had become entitled to old-age insurance benefits in the month in which the application for disability insurance benefits was filed and he was entitled to an old-age insurance benefit for each month for which (pursuant to subsection (b)) he was entitled to a disability insurance benefit. For the purposes of the preceding sentence, in the case of an individual who attained age 62 in or before the first month referred to in subparagraph (A) or (B) of such sentence, as the case may be, the elapsed years referred to in section 415(b)(3) of this title shall not include the year in which he attained age 62, or any year thereafter."],[0,"(b) Filing application"],[0,"An application for disability insurance benefits filed before the first month in which the applicant satisfies the requirements for such benefits (as prescribed in subsection (a)(1)) shall be deemed a valid application (and shall be deemed to have been filed in such first month) only if the applicant satisfies the requirements for such benefits before the Commissioner of Social Security makes a final decision on the application and no request under section 405(b) of this title for notice and opportunity for a hearing thereon is made, or if such a request is made, before a decision based upon the evidence adduced at the hearing is made (regardless of whether such decision becomes the final decision of the Commissioner of Social Security). An individual who would have been entitled to a disability insurance benefit for any month had he filed application therefor before the end of such month shall be entitled to such benefit for such month if such application is filed before the end of the 12th month immediately succeeding such month."],[0,"(c) Definitions; insured status; waiting period"],[0,"For purposes of this section—"],[1,"(1) An individual shall be insured for disability insurance benefits in any month if—"],[2,"(A) he would have been a fully insured individual (as defined in section 414 of this title) had he attained age 62 and filed application for benefits under section 402(a) of this title on the first day of such month, and"],[2,"(B)(i) he had not less than 20 quarters of coverage during the 40-quarter period which ends with the quarter in which such month occurred, or"],[2,"(ii) if such month ends before the quarter in which he attains (or would attain) age 31, not less than one-half (and not less than 6) of the quarters during the period ending with the quarter in which such month occurred and beginning after he attained the age of 21 were quarters of coverage, or (if the number of quarters in such period is less than 12) not less than 6 of the quarters in the 12-quarter period ending with such quarter were quarters of coverage, or"],[2,"(iii) in the case of an individual (not otherwise insured under clause (i)) who, by reason of section 416(i)(3)(B)(ii) of this title, had a prior period of disability that began during a period before the quarter in which he or she attained age 31, not less than one-half of the quarters beginning after such individual attained age 21 and ending with the quarter in which such month occurs are quarters of coverage, or (if the number of quarters in such period is less than 12) not less than 6 of the quarters in the 12-quarter period ending with such quarter are quarters of coverage;"],[1,"except that the provisions of subparagraph (B) of this paragraph shall not apply in the case of an individual who is blind (within the meaning of \"blindness\" as defined in section 416(i)(1) of this title). For purposes of subparagraph (B) of this paragraph, when the number of quarters in any period is an odd number, such number shall be reduced by one, and a quarter shall not be counted as part of any period if any part of such quarter was included in a period of disability unless such quarter was a quarter of coverage."],[1,"(2) The term \"waiting period\" means, in the case of any application for disability insurance benefits, the earliest period of five consecutive calendar months—"],[2,"(A) throughout which the individual with respect to whom such application is filed has been under a disability, and"],[2,"(B)(i) which begins not earlier than with the first day of the seventeenth month before the month in which such application is filed if such individual is insured for disability insurance benefits in such seventeenth month, or (ii) if he is not so insured in such month, which begins not earlier than with the first day of the first month after such seventeenth month in which he is so insured."],[1,"Notwithstanding the preceding provisions of this paragraph, no waiting period may begin for any individual before January 1, 1957."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/423?type=usc&year=mostrecent&link-type=html"},"head":"§423. Disability insurance benefit payments","tname":"The Public Health and Welfare","by":{"0":"6, 1, 10","1":"2, 2, 2, 5"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 1382c","url":"https://www.law.cornell.edu/uscode/text/42/1382c","subs":["(a)(3)(B)","(a)(3)(A)"],"stext":{"head":"§1382c. Definitions","paras":[[0,"(a)(1) For purposes of this subchapter, the term \"aged, blind, or disabled individual\" means an individual who—"],[1,"(A) is 65 years of age or older, is blind (as determined under paragraph (2)), or is disabled (as determined under paragraph (3)), and"],[1,"(B)(i) is a resident of the United States, and is either (I) a citizen or (II) an alien lawfully admitted for permanent residence or otherwise permanently residing in the United States under color of law (including any alien who is lawfully present in the United States as a result of the application of the provisions of section 1182(d)(5) of title 8), or"],[1,"(ii) is a child who is a citizen of the United States, and who is living with a parent of the child who is a member of the Armed Forces of the United States assigned to permanent duty ashore outside the United States."],[0,"(2) An individual shall be considered to be blind for purposes of this subchapter if he has central visual acuity of 20/200 or less in the better eye with the use of a correcting lens. An eye which is accompanied by a limitation in the fields of vision such that the widest diameter of the visual field subtends an angle no greater than 20 degrees shall be considered for purposes of the first sentence of this subsection as having a central visual acuity of 20/200 or less. An individual shall also be considered to be blind for purposes of this subchapter if he is blind as defined under a State plan approved under subchapter X or XVI as in effect for October 1972 and received aid under such plan (on the basis of blindness) for December 1973, so long as he is continuously blind as so defined."],[0,"(3)(A) Except as provided in subparagraph (C), an individual shall be considered to be disabled for purposes of this subchapter if he is unable to engage in any substantial gainful activity by reason of any medically determinable physical or mental impairment which can be expected to result in death or which has lasted or can be expected to last for a continuous period of not less than twelve months."],[0,"(B) For purposes of subparagraph (A), an individual shall be determined to be under a disability only if his physical or mental impairment or impairments are of such severity that he is not only unable to do his previous work but cannot, considering his age, education, and work experience, engage in any other kind of substantial gainful work which exists in the national economy, regardless of whether such work exists in the immediate area in which he lives, or whether a specific job vacancy exists for him, or whether he would be hired if he applied for work. For purposes of the preceding sentence (with respect to any individual), \"work which exists in the national economy\" means work which exists in significant numbers either in the region where such individual lives or in several regions of the country."],[0,"(C)(i) An individual under the age of 18 shall be considered disabled for the purposes of this subchapter if that individual has a medically determinable physical or mental impairment, which results in marked and severe functional limitations, and which can be expected to result in death or which has lasted or can be expected to last for a continuous period of not less than 12 months."],[0,"(ii) Notwithstanding clause (i), no individual under the age of 18 who engages in substantial gainful activity (determined in accordance with regulations prescribed pursuant to subparagraph (E)) may be considered to be disabled."],[0,"(D) For purposes of this paragraph, a physical or mental impairment is an impairment that results from anatomical, physiological, or psychological abnormalities which are demonstrable by medically acceptable clinical and laboratory diagnostic techniques."],[0,"(E) The Commissioner of Social Security shall by regulations prescribe the criteria for determining when services performed or earnings derived from services demonstrate an individual's ability to engage in substantial gainful activity. In determining whether an individual is able to engage in substantial gainful activity by reason of his earnings, where his disability is sufficiently severe to result in a functional limitation requiring assistance in order for him to work, there shall be excluded from such earnings an amount equal to the cost (to such individual) of any attendant care services, medical devices, equipment, prostheses, and similar items and services (not including routine drugs or routine medical services unless such drugs or services are necessary for the control of the disabling condition) which are necessary (as determined by the Commissioner of Social Security in regulations) for that purpose, whether or not such assistance is also needed to enable him to carry out his normal daily functions; except that the amounts to be excluded shall be subject to such reasonable limits as the Commissioner of Social Security may prescribe. Notwithstanding the provisions of subparagraph (B), an individual whose services or earnings meet such criteria shall be found not to be disabled. The Commissioner of Social Security shall make determinations under this subchapter with respect to substantial gainful activity, without regard to the legality of the activity."],[0,"(F) Notwithstanding the provisions of subparagraphs (A) through (E), an individual shall also be considered to be disabled for purposes of this subchapter if he is permanently and totally disabled as defined under a State plan approved under subchapter XIV or XVI as in effect for October 1972 and received aid under such plan (on the basis of disability) for December 1973 (and for at least one month prior to July 1973), so long as he is continuously disabled as so defined."],[0,"(G) In determining whether an individual's physical or mental impairment or impairments are of a sufficient medical severity that such impairment or impairments could be the basis of eligibility under this section, the Commissioner of Social Security shall consider the combined effect of all of the individual's impairments without regard to whether any such impairment, if considered separately, would be of such severity. If the Commissioner of Social Security does find a medically severe combination of impairments, the combined impact of the impairments shall be considered throughout the disability determination process."],[0,"(H)(i) In making determinations with respect to disability under this subchapter, the provisions of sections 421(h), 421(k), and 423(d)(5) of this title shall apply in the same manner as they apply to determinations of disability under subchapter II."],[0,"(ii)(I) Not less frequently than once every 3 years, the Commissioner shall review in accordance with paragraph (4) the continued eligibility for benefits under this subchapter of each individual who has not attained 18 years of age and is eligible for such benefits by reason of an impairment (or combination of impairments) which is likely to improve (or, at the option of the Commissioner, which is unlikely to improve)."],[0,"(II) A representative payee of a recipient whose case is reviewed under this clause shall present, at the time of review, evidence demonstrating that the recipient is, and has been, receiving treatment, to the extent considered medically necessary and available, of the condition which was the basis for providing benefits under this subchapter."],[0,"(III) If the representative payee refuses to comply without good cause with the requirements of subclause (II), the Commissioner of Social Security shall, if the Commissioner determines it is in the best interest of the individual, promptly suspend payment of benefits to the representative payee, and provide for payment of benefits to an alternative representative payee of the individual or, if the interest of the individual under this subchapter would be served thereby, to the individual."],[0,"(IV) Subclause (II) shall not apply to the representative payee of any individual with respect to whom the Commissioner determines such application would be inappropriate or unnecessary. In making such determination, the Commissioner shall take into consideration the nature of the individual's impairment (or combination of impairments). Section 1383(c) of this title shall not apply to a finding by the Commissioner that the requirements of subclause (II) should not apply to an individual's representative payee."],[0,"(iii) If an individual is eligible for benefits under this subchapter by reason of disability for the month preceding the month in which the individual attains the age of 18 years, the Commissioner shall redetermine such eligibility—"],[1,"(I) by applying the criteria used in determining initial eligibility for individuals who are age 18 or older; and"],[1,"(II) either during the 1-year period beginning on the individual's 18th birthday or, in lieu of a continuing disability review, whenever the Commissioner determines that an individual's case is subject to a redetermination under this clause."],[0,"With respect to any redetermination under this clause, paragraph (4) shall not apply."],[0,"(iv)(I) Except as provided in subclause (VI), not later than 12 months after the birth of an individual, the Commissioner shall review in accordance with paragraph (4) the continuing eligibility for benefits under this subchapter by reason of disability of such individual whose low birth weight is a contributing factor material to the Commissioner's determination that the individual is disabled."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1382c?type=usc&year=mostrecent&link-type=html"},"head":"§1382c. Definitions","tname":"The Public Health and Welfare","by":{"0":"2, 10","1":"2, 2, 5"}},{"t":"law","label":"Pub. L. No. 104-104","url":"https://www.govinfo.gov/link/plaw/104/public/104","by":{"0":"30"}},{"t":"reg","label":"20 C.F.R. § 404.902","url":"https://www.ecfr.gov/current/title-20/section-404.902","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.907","url":"https://www.ecfr.gov/current/title-20/section-404.907","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.914","url":"https://www.ecfr.gov/current/title-20/section-404.914","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.920","url":"https://www.ecfr.gov/current/title-20/section-404.920","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.950","url":"https://www.ecfr.gov/current/title-20/section-404.950","subs":["(d)"],"by":{"0":"24"}},{"t":"reg","label":"20 C.F.R. § 404.967","url":"https://www.ecfr.gov/current/title-20/section-404.967","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.981","url":"https://www.ecfr.gov/current/title-20/section-404.981","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.1503","url":"https://www.ecfr.gov/current/title-20/section-404.1503","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.1505","url":"https://www.ecfr.gov/current/title-20/section-404.1505","by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 404.1512","url":"https://www.ecfr.gov/current/title-20/section-404.1512","subs":["(b)(3)"],"by":{"0":"10"}},{"t":"reg","label":"20 C.F.R. § 404.1520","url":"https://www.ecfr.gov/current/title-20/section-404.1520","subs":["(a)(4)(i)","(a)(4)(ii)","(a)(4)(iii)","(a)(4)(iv)","(a)(4)(v)"],"by":{"0":"9, 9, 9, 9, 2, 3, 10"}},{"t":"reg","label":"20 C.F.R. § 404.1563","url":"https://www.ecfr.gov/current/title-20/section-404.1563","subs":["(d)"],"by":{"0":"17"}},{"t":"reg","label":"20 C.F.R. § 404.1566","url":"https://www.ecfr.gov/current/title-20/section-404.1566","subs":["(d)","(e)"],"by":{"0":"12, 10"}},{"t":"reg","label":"20 C.F.R. § 404.1567","url":"https://www.ecfr.gov/current/title-20/section-404.1567","subs":["(a)","(b)"],"by":{"0":"50, 50"}},{"t":"reg","label":"20 C.F.R. § 416.903","url":"https://www.ecfr.gov/current/title-20/section-416.903","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.905","url":"https://www.ecfr.gov/current/title-20/section-416.905","by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 416.912","url":"https://www.ecfr.gov/current/title-20/section-416.912","subs":["(b)(3)"],"by":{"0":"10"}},{"t":"reg","label":"20 C.F.R. § 416.920","url":"https://www.ecfr.gov/current/title-20/section-416.920","subs":["(a)(4)(i)","(a)(4)(ii)","(a)(4)(iii)","(a)(4)(iv)","(a)(4)(v)"],"by":{"0":"9, 9, 9, 9, 3, 10"}},{"t":"reg","label":"20 C.F.R. § 416.963","url":"https://www.ecfr.gov/current/title-20/section-416.963","subs":["(d)"],"by":{"0":"17"}},{"t":"reg","label":"20 C.F.R. § 416.966","url":"https://www.ecfr.gov/current/title-20/section-416.966","subs":["(d)","(e)"],"by":{"0":"12, 10"}},{"t":"reg","label":"20 C.F.R. § 416.1402","url":"https://www.ecfr.gov/current/title-20/section-416.1402","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.1407","url":"https://www.ecfr.gov/current/title-20/section-416.1407","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.1414","url":"https://www.ecfr.gov/current/title-20/section-416.1414","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.1429","url":"https://www.ecfr.gov/current/title-20/section-416.1429","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.1467","url":"https://www.ecfr.gov/current/title-20/section-416.1467","by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 416.1481","url":"https://www.ecfr.gov/current/title-20/section-416.1481","by":{"0":"9"}},{"t":"case","label":"Abrams v. United States","cite":"250 U.S. 616","y":1919,"id":"1900-1940/250us616","sc":1,"sum":"The Court found that the Espionage Act did not violate the First Amendment if the speech incited resistance to war.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Anderson v. Liberty Lobby, Inc.","cite":"477 U.S. 242","y":1986,"id":"1985/84-1602","sc":1,"op":1,"sum":"In a 6-to-3 opinion, the Court held that the purpose of summary judgments is to determine if the evidence is so one-sided that a party should prevail as a matter of law. Summary judgments will not lie if there is a sufficient likelihood that a reasonable jury would return a verdict favorable to the nonmoving party.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Appalachian Elec. Power Co. v. NLRB","cite":"93 F.2d 985","y":1938,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/93/985/","by":{"1":"25, 26"}},{"t":"case","label":"Ballston-Stillwater Knitting Co. v. NLRB","cite":"98 F.2d 758","y":1938,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/98/758/","by":{"1":"25"}},{"t":"case","label":"Bowen v. Galbreath","cite":"485 U.S. 74","y":1988,"id":"1987/86-1146","sc":1,"sum":"A district court does not have the authority to order the Secretary to withhold a portion of past-due SSI benefits for the payment of attorney's fees received in judicial proceedings under Title XVI. Pp. 75-79. 799 F. 2d 370, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Buck v. Berryhill","cite":"869 F.3d 1040","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/1040/","by":{"1":"51"}},{"t":"case","label":"Califano v. Boles","cite":"443 U.S. 282","y":1979,"id":"1978/78-808","sc":1,"sum":"Section 202 (g) (1) of the Social Security Act restricting \"mother's insurance benefits\" to widows and divorced wives of wage earners does not violate the equal protection component of the Due Process Clause of the Fifth Amendment by thus denying such benefits to the mother of an illegitimate child because she was never married to the wage earner who fathered the child.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"53"}},{"t":"case","label":"Chicago Junction Ry. Co. v. King","cite":"222 U.S. 222","y":1911,"id":"scdb/1911-014","sc":1,"op":1,"sum":"Where the cause of action is based on a statute of the United States there-is an appeal to this court from the judgment of the Circuit Court of Appeals.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Consolo v. Federal Mar. Comm’n","cite":"383 U.S. 607","y":1966,"id":"1965/63","sc":1,"by":{"1":"26, 27"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Dowling v. United States","cite":"493 U.S. 342","y":1990,"id":"1989/88-6025","sc":1,"sum":"Petitioner Dowling was convicted of robbing a Virgin Islands bank while wearing a ski mask and carrying a small pistol. Relying on Federal Rule of Evidence 404(b)-which provides that evidence of other crimes, wrongs, or acts may be admissible against a defendant for purposes other than character evidence-the Government introduced at trial the testimony of one Henry, who stated that a similarly masked and armed …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Gunning v. Cooley","cite":"281 U.S. 90","y":1930,"id":"scdb/1929-028","sc":1,"by":{"1":"25, 26"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Illinois Cent. R.R. v. Norfolk & W. Ry. Co.","cite":"385 U.S. 57","y":1966,"id":"1966/15","sc":1,"by":{"1":"26"}},{"t":"case","label":"Liskowitz v. Astrue","cite":"559 F.3d 736","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/736/","by":{"1":"54"}},{"t":"case","label":"Lockhart v. Nelson","cite":"488 U.S. 33","y":1988,"id":"1988/87-1277","sc":1,"sum":"When a reviewing court determines that a defendant's conviction must be set aside because certain evidence was erroneously admitted against him, and further finds that once that evidence is discounted, there is insufficient evidence to support the conviction, the Double Jeopardy Clause does not forbid his retrial so long as the sum of the evidence offered by the State and admitted by the trial court-whether …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"ar":1,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"1":"34, 35"}},{"t":"case","label":"McDaniel v. Brown","cite":"558 U.S. 120","y":2010,"id":"2009/08-559","sc":1,"sum":"A case, regarding the rape of a nine-year-old girl and the subsequent conviction of the suspected rapist, in which the Court held that a federal court did not have the authority to make a ruling based on a DNA report submitted on appeal, rather than to the original trial court, based on the habeas corpus review standard established in Jackson v. Virginia.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"NLRB v. Thompson Prods., Inc.","cite":"97 F.2d 13","y":1938,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/97/13/","by":{"1":"25"}},{"t":"case","label":"Stilson v. United States","cite":"250 U.S. 583","y":1919,"id":"scdb/1919-009","sc":1,"sum":"The denial of a severance in a criminal case is within the discretion of the judge.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Union Pac. R.R. v. Huxoll","cite":"245 U.S. 535","y":1918,"id":"scdb/1917-194","sc":1,"sum":"The question, whether any substantial evidence was introduced to justify submission of a case to the jury on the issue of proximate causal negligence is one of law, reviewable by this court, in an action under the Federal Employers’ Liability Act, coming from a state court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Carlo Bianchi & Co.","cite":"373 U.S. 709","y":1963,"id":"1962/529","sc":1,"sum":"In a suit on a government contract, apart from questions of fraud, determination of the finality to be attached to a departmental decision on a question arising under a \"disputes\" clause must rest solely on consideration of the record before the department, and no new evidence may be received or considered. Pp. 709-718. 157 Ct. Cl. -, judgment vacated and cause remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 19, 24, 26, 27, 30"}},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"sum":"The National Labor Relations Board ordered petitioner to reinstate with back pay an employee found to have been discharged because he gave certain testimony in another proceeding under the National Labor Relations Act. The evidence as to the reason for his discharge was conflicting; and the Board overruled its examiner's findings of fact and his recommendation that the proceedings be dismissed. In decreeing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 26"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Wood v. Allen","cite":"558 U.S. 290","y":2010,"id":"2009/08-9156","sc":1,"sum":"The Court held that an inmate's conviction was proper, despite the fact that his attorney failed to properly investigate or introduce evidence that his IQ was well below average.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"28"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"28"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"28"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(D)","(2)(E)"],"by":{"1":"2, 2"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","stext":{"head":"§301. Authorization of appropriations","paras":[[0,"For the purpose of enabling each State, as far as practicable under the conditions in such State, to furnish financial assistance to aged needy individuals, there is hereby authorized to be appropriated for each fiscal year a sum sufficient to carry out the purposes of this subchapter. The sums made available under this section shall be used for making payments to States which have submitted, and had approved by the Secretary of Health and Human Services (hereinafter referred to as the \"Secretary\"), State plans for old-age assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Authorization of appropriations","tname":"The Public Health and Welfare","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1381a","url":"https://www.law.cornell.edu/uscode/text/42/1381a","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","subs":["(c)(1)(A)","(c)(3)","(d)(1)"],"by":{"1":"25, 25, 25"}},{"t":"usc","label":"2 U.S.C. § 1407","url":"https://www.law.cornell.edu/uscode/text/2/1407","subs":["(d)(3)"],"by":{"1":"36"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(c)(3)"],"by":{"1":"36"}},{"t":"usc","label":"12 U.S.C. § 1848","url":"https://www.law.cornell.edu/uscode/text/12/1848","by":{"1":"36"}},{"t":"usc","label":"15 U.S.C. § 717r","url":"https://www.law.cornell.edu/uscode/text/15/717r","subs":["(b)"],"by":{"1":"36"}},{"t":"usc","label":"21 U.S.C. § 877","url":"https://www.law.cornell.edu/uscode/text/21/877","by":{"1":"36"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"by":{"1":"36"}},{"t":"usc","label":"29 U.S.C. § 660","url":"https://www.law.cornell.edu/uscode/text/29/660","subs":["(a)"],"by":{"1":"36"}},{"t":"usc","label":"30 U.S.C. § 816","url":"https://www.law.cornell.edu/uscode/text/30/816","subs":["(a)(1)"],"by":{"1":"36"}},{"t":"usc","label":"49 U.S.C. § 44703","url":"https://www.law.cornell.edu/uscode/text/49/44703","subs":["(d)(3)"],"by":{"1":"36"}},{"t":"rule","label":"Fed. R. Evid. 702","url":"https://www.law.cornell.edu/rules/fre/rule_702","by":{"1":"46"}},{"t":"reg","label":"68 Fed. Reg. 51,153","url":"https://www.govinfo.gov/link/fr/68/51153","by":{"1":"47"}},{"t":"reg","label":"Social Sec. Ruling 00-4p, Titles II and XVI: Use of Vocational Expert and Vocational Specialist Evidence, and Other Reliable Occupational In, 65 Fed. Reg. 75,759","url":"https://www.govinfo.gov/link/fr/65/75759","by":{"1":"9"}},{"t":"case","label":"Alabama Power Co. v. Federal Power Commission","cite":"511 F.2d 383","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/511/383/","by":{"2":"16"}},{"t":"case","label":"Barrett v. Berryhill","cite":"906 F.3d 340","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/906/340/","by":{"2":"20"}},{"t":"case","label":"Beard v. Banks","cite":"548 U.S. 521","y":2006,"id":"2005/04-1739","sc":1,"sum":"The plurality opinion by Justice Breyer held that Banks had failed to present sufficient evidence that the prison had acted unreasonably in denying newspapers, magazines, and photographs to its most troublesome inmates.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Cleveland Board of Education v. Loudermill","cite":"470 U.S. 532","y":1985,"id":"1984/83-1362","sc":1,"sum":"The Court found that \"affording the employee an opportunity to respond prior to termination would impose neither a significant administrative burden nor intolerable delays.\" Accordingly, the significant interests of the employees to retain their jobs outweighed the interests of the state to remove employees quickly.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Connecticut v. Doehr","cite":"501 U.S. 1","y":1991,"id":"1990/90-143","sc":1,"sum":"The judgment is affirmed. 898,F. 2d 852, affirmed. JUSTICE WHITE delivered the opinion of the Court with respect to Parts 1, 11, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Fuentes v. Shevin","cite":"407 U.S. 67","y":1972,"id":"1971/70-5039","sc":1,"sum":"Appellants, most of whom were purchasers of household goods under conditional sales contracts, challenge the constitutionality of prejudgment replevin provisions of Florida law (in No. 70-5039) and Pennsylvania law (in No. 70-5138). These provisions permit a private party, withouit a hearing or prior notice to the other party, to obtain a prejudgment writ of replevin through a summary process of ex parte application …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Herrmann v. Colvin","cite":"772 F.3d 1110","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1110/","by":{"2":"8"}},{"t":"case","label":"Interstate Circuit v. United States","cite":"306 U.S. 208","y":1939,"id":"scdb/1938-078","sc":1,"op":1,"sum":"1. Where distributors of motion picture films, owning or controlling the copyrights and engaged, interstate, in the business of supplying the films to theaters for exhibition under license contracts, join in making and carrying out an agreement with the owners of the theaters in certain cities to whom their licenses for first run exhibitions of \"feature\" pictures in those cities are confined, whereby the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Nelson v. Colorado","cite":"137 S. Ct. 1249","y":2017,"id":"2016/15-1256","sc":1,"sum":"The Court decided that the Colorado Exoneration Act, which requires exonerated persons to “prove, by clear and convincing evidence, that they were ‘actually innocent’” in order to refund their money, does not comport with the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Saylor v. United States Department of Agriculture","cite":"723 F.2d 581","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/723/581/","by":{"2":"16"}},{"t":"case","label":"United States v. L.A. Tucker Truck Lines, Inc.","cite":"344 U.S. 33","y":1952,"id":"scdb/1952-007","sc":1,"sum":"The district court should not entertain this objection when first made at that stage of the proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}}]};